#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Immersive

Viewpoint {
  position 0 0 20
}

DEF T TimeSensor {
  cycleInterval 2
  loop TRUE
  startTime 946684800
}

DEF PI PositionInterpolator {
  key [
    0,
    0.5,
    1
  ]
  keyValue [
    0 0 0,
    0 0 30,
    0 0 0
  ]
}

DEF PI2 PositionInterpolator {
  key [
    0,
    0.5,
    1
  ]
  keyValue [
    -20 0 0,
    20 0 0,
    -20 0 0
  ]
}

DEF MOVE Transform {
  translation 0 0 0.4999995
  children [
    DEF PS ProximitySensor {
      size 6 6 6
    }
    Shape {
      geometry Box {
        size 1 1 1
      }
    }
  ]
}

DEF VMOVE Transform {
  translation -19.33333 0 0
  children [
    DEF VS VisibilitySensor {
      size 4 4 4
    }
    Shape {
      geometry Box { }
    }
  ]
}

DEF OBS Script {
  inputOutput SFTime     pEnter 0
  inputOutput SFTime     pExit 0
  inputOutput SFBool     pActive FALSE
  inputOutput SFVec3f    pPos 0 0 0
  inputOutput SFRotation pRot 0 0 1 0
  inputOutput SFTime     vEnter 0
  inputOutput SFTime     vExit 0
  inputOutput SFBool     vActive FALSE

  url "ecmascript:
function noop () { }
"
}

ROUTE T.fraction_changed TO PI.set_fraction
ROUTE T.fraction_changed TO PI2.set_fraction
ROUTE PI.value_changed TO MOVE.set_translation
ROUTE PI2.value_changed TO VMOVE.set_translation
ROUTE PS.enterTime TO OBS.set_pEnter
ROUTE PS.exitTime TO OBS.set_pExit
ROUTE PS.isActive TO OBS.set_pActive
ROUTE PS.position_changed TO OBS.set_pPos
ROUTE PS.orientation_changed TO OBS.set_pRot
ROUTE VS.enterTime TO OBS.set_vEnter
ROUTE VS.exitTime TO OBS.set_vExit
ROUTE VS.isActive TO OBS.set_vActive

